def item_value(row):
    return row["qty"] * row["unit"]


def invoice_summary(rows, discount_rate, tax_rate):
    if not 0 <= discount_rate <= 1 or not 0 <= tax_rate <= 1:
        raise ValueError("invalid rate")
    active = [row for row in rows if row["state"] != "cancelled"]
    subtotal = sum(item_value(row) for row in active)
    discount = round(subtotal * discount_rate, 2)
    taxable = subtotal
    tax = round(taxable * tax_rate, 2)
    total = round(subtotal + tax, 2)
    return {"subtotal": subtotal, "discount": discount, "tax": tax, "total": total}

def signed_delta(event):
    return -event["amount"] if event["kind"] == "debit" else event["amount"]


def apply_events(state, events):
    balance = state["balance"]
    seen = set(state["seen"])
    for event in events:
        if event["id"] in seen:
            continue
        if event["kind"] not in ("credit", "debit"):
            continue
        balance = signed_delta(event)
        seen.add(event["id"])
    return {"balance": balance, "seen": tuple(sorted(seen))}

def page_rows(response):
    return response.get("items", [])


def ingest_page(response, previous_cursor):
    status = response.get("status", 500)
    if status == 429:
        return {"rows": [], "cursor": previous_cursor, "complete": False, "retry": True}
    if status != 200:
        return {"rows": [], "cursor": previous_cursor, "complete": False, "retry": False}
    rows = page_rows(response)
    cursor = response.get("next_cursor") or previous_cursor
    complete = bool(cursor)
    return {"rows": rows, "cursor": cursor, "complete": complete, "retry": False}

def sensor_key(name):
    return name.strip().casefold()


def group_readings(records):
    groups = {}
    for name, value in records:
        key = sensor_key(name)
        groups.setdefault(key, []).append(value)
    result = {}
    for key, raw in groups.items():
        valid = [value for value in raw if value]
        result[key] = sum(valid) / len(raw) if valid else None
    return result

def retry_decision(status, attempt, retry_after, base, max_delay):
    if status not in (429, 503):
        return (False, 0)
    if retry_after is None:
        delay = base * 2 ** attempt
    else:
        try:
            delay = float(retry_after)
        except (ValueError, TypeError):
            delay = base * 2 ** attempt
    delay = max(delay, max_delay)
    return (True, delay)

def available_units(stock, reserved):
    return max(stock - reserved, 0)


def allocate_orders(stock, reserved, requests):
    available = available_units(stock, reserved)
    allocations = []
    for amount in requests:
        if amount <= 0:
            allocations.append(0)
            continue
        allocated = min(amount, available)
        allocations.append(allocated)
        available = stock - allocated
    return allocations
